<?php require_once 'bootstrap.php';$u=require_login();$sic=$_GET['sic']??$_POST['sic']??'';$st=db()->prepare('SELECT * FROM projects WHERE sic_id=?');$st->execute([$sic]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Progetto non trovato');}$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$act=$_POST['act']??'';if($act==='volunteer'){$hours=max(0,(float)$_POST['hours']);$vs=sic_id();db()->prepare('INSERT INTO volunteer_actions(sic_id,project_sic_id,user_sic_id,hours,description,verified) VALUES(?,?,?,?,?,0)')->execute([$vs,$sic,$u['sic_id'],$hours,trim($_POST['description'])]);$msg='Attività inviata: il DRX viene assegnato solo dopo verifica.';}elseif($act==='donate'){$amount=max(0,(float)$_POST['amount']);db()->prepare('INSERT INTO donations(sic_id,project_sic_id,donor_user_sic_id,amount_eur,anonymous) VALUES(?,?,?,?,?)')->execute([sic_id(),$sic,$u['sic_id'],$amount,isset($_POST['anonymous'])?1:0]);$msg='Impegno di donazione registrato. Il pagamento non è considerato ricevuto finché non viene confermato dal sistema di tesoreria. Nessun DRX Rank viene acquistato.';}}$sum=db()->prepare('SELECT COALESCE(SUM(amount_eur),0) FROM donations WHERE project_sic_id=?');$sum->execute([$sic]);$don=(float)$sum->fetchColumn();$pageTitle=$p['title'];require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Social Impact</span><h1><?=h($p['title'])?></h1><p><?=h($p['description'])?></p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="metric-grid"><div class="metric"><b>€ <?=number_format($don,2,',','.')?></b><span>Raccolti</span></div><div class="metric"><b><?=h($p['status'])?></b><span>Status</span></div></section><section class="home-modules"><article><h3>Volontariato</h3><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="sic" value="<?=h($sic)?>"><input type="hidden" name="act" value="volunteer"><input type="number" step="0.5" min="0.5" name="hours" placeholder="Ore" required><textarea name="description" placeholder="Cosa hai fatto" required></textarea><button class="btn primary">Invia per verifica</button></form></article><article><h3>Impegno di donazione</h3><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="sic" value="<?=h($sic)?>"><input type="hidden" name="act" value="donate"><input type="number" step="0.01" min="1" name="amount" placeholder="€" required><label><input type="checkbox" name="anonymous"> Mostra come anonima</label><button class="btn">Registra impegno</button></form></article></section><?php require '_footer.php';?>